    intake_date = 'January, February, April, May, July, August, September, November',
    updated_at = NOW()
WHERE cricos_provider_code = '03854G';

UPDATE courses SET
    course_description = '<div> <div> <p>This qualification reflects the role of individuals who apply knowledge, practical skills and experience in leadership and management across a range of enterprise and industry contexts.</p><p>Individuals at this level display initiative and judgement in planning, organising, implementing and monitoring their own workload and the workload of others. They use communication skills to support individuals and teams to meet organisational or enterprise requirements.</p><p>They plan, design, apply and evaluate solutions to unpredictable problems, and identify, analyse and synthesise information from a variety of sources.</p> </div> </div>',
    total_course_duration = '52 weeks',
    offshore_tuition_fee = 17800,
    onshore_tuition_fee = 17800,
    enrolment_fee = 250,
    materials_fee = 400,
    entry_requirements = '<h4>Entry Requirements</h4><div><p>Australian Federation College has the following entry requirements. You must:</p><ul><li>Be at least 18 years of age at commencement of course;</li><li>Have completed Australian year 12 or equivalent OR successfully completed AQF Cert IV qualification or above;</li><li>Prior commencement, participate in a non-intrusive course entry assessment to determine suitability for the course and student needs. Where support needs are identified, Australian Federation College may implement support strategies, develop a Student Support Plan, provide additional learning support or recommend alternative study pathways where appropriate. The assessment can be accessed through the LLND Portal- <a href="https://learn.afcollege.edu.au/login">https://learn.afcollege.edu.au/login</a></li><li>Meet Australian student visa subclass 500 requirements;</li><li>Have an IELTS* score of 6 (test results must be no more than 2 years old).</li></ul><p>English language competence can also be demonstrated through documented evidence of any of the following:</p><ul><li>Educated for at least 5 years in an English-speaking country where the medium of instructions was in English; or</li><li>Completed at least a Certificate IV level course in an Australian RTO.</li></ul><p>*<em>Note that other English language tests such as PTE and TOEFL can be accepted. Students are required to provide their results so that Australian Federation College can confirm they are equivalent to IELTS 6. Refer to ECT for further guidance. </em></p></div>',
    apply_form = 'https://afcollege.edu.au/bsb50420-diploma-of-leadership-and-management/',
    updated_at = NOW()
WHERE cricos_course_code = '104415A';
UPDATE courses SET
    course_description = '<div> <div> <p>This qualification reflects the role of individuals who apply specialised knowledge and skills, together with experience in leadership and management, across a range of enterprise and industry contexts.</p><p><br/>Individuals at this level use initiative and judgement to plan and implement a range of leadership and management functions, with accountability for personal and team outcomes within broad parameters.</p><p><br/>They use cognitive and communication skills to identify, analyse and synthesise information from a variety of sources and transfer their knowledge to others, and creative or conceptual skills to express ideas and perspectives or respond to complex problems.</p> </div> </div>',
    total_course_duration = '52 weeks',
    offshore_tuition_fee = 11800,
    onshore_tuition_fee = 11800,
    enrolment_fee = 250,
    materials_fee = 400,
    entry_requirements = '<h4>Entry Requirements</h4><div><p>Australian Federation College has the following entry requirements. You must:</p><ul><li>Be at least 18 years of age at commencement of course;</li><li>Have completed a Diploma or Advanced Diploma from the BSB Training Package (current or superseded equivalent versions) such as BSB50420; or have two years’ equivalent full-time relevant work experience in an operational or leadership role in an enterprise.</li><li>Prior commencement, participate in a non-intrusive course entry assessment to determine suitability for the course and student needs. Where support needs are identified, Australian Federation College may implement support strategies, develop a Student Support Plan, provide additional learning support or recommend alternative study pathways where appropriate. The assessment can be accessed through the LLND Portal- <a href="https://learn.afcollege.edu.au/login">https://learn.afcollege.edu.au/login</a></li><li>Meet Australian student visa subclass 500 requirements;</li><li>Have an IELTS* score of 6 (test results must be no more than 2 years old).</li></ul><p>English language competence can also be demonstrated through documented evidence of any of the following:</p><ul><li>Educated for at least 5 years in an English-speaking country where the medium of instructions was in English; or</li><li>Completed at least a Certificate IV level course in an Australian RTO.</li></ul><p>*<em>Note that other English language tests such as PTE and TOEFL can be accepted. Students are required to provide their results so that Australian Federation College can confirm they are equivalent to IELTS 6. Refer to ECT for further guidance.</em></p></div>',
    apply_form = 'https://afcollege.edu.au/bsb60420-advanced-diploma-of-leadership-and-management/',
    updated_at = NOW()
WHERE cricos_course_code = '108185M';
UPDATE courses SET
    course_description = '<div> <div> <p>This qualification reflects the role of individuals who apply highly specialised knowledge and skills in the field of organisational learning and capability development. Individuals in these roles generate and evaluate complex ideas. They also initiate, design and execute major learning and development functions within an organisation. Typically, they would have full responsibility and accountability for the personal output and work of others.<br/>This qualification may apply to leaders and managers in an organisation where learning is used to build organisational capability. The job roles that relate to this qualification may also include RTO Manager and RTO Director.</p> </div> </div>',
