    course_description = '<div> <div> <p>This qualification reflects the role of an individual working as a senior civil works designer or a para-professional designer, who supports professional engineers. They perform tasks that are broad, specialised, complex and technical and include strategic areas and initiating activities. They are responsible for the design of complex projects to ensure the implementation of the client’s site requirements and are required to demonstrate self-directed application of theoretical and technical knowledge and initiate solutions to technical problems or management requirements.<br/><br/><strong>Licensing, legislative, regulatory or certification considerations<br/><br/></strong>Licensing, legislative, regulatory and certification requirements that apply to this qualification can vary between states, territories and industry sectors. Users must check requirements with relevant body before applying the qualification.</p> </div> </div>',
    total_course_duration = '104 weeks',
    offshore_tuition_fee = 30000,
    onshore_tuition_fee = 30000,
    enrolment_fee = 250,
    materials_fee = 1000,
    entry_requirements = '<h4>Entry Requirements</h4><div><p>Australian Federation College has the following entry requirements:</p><ul><li>Be at least 18 years of age at course commencement;</li><li>Have completed Australian year 12 or equivalent OR successfully completed AQF Certificate IV qualification or above;</li><li>Prior commencement, participate in a non-intrusive course entry assessment to determine suitability for the course and student needs. Where support needs are identified, Australian Federation College may implement support strategies, develop a Student Support Plan, provide additional learning support or recommend alternative study pathways where appropriate. The assessment can be accessed through the LLND Portal- <a href="https://learn.afcollege.edu.au/login">https://learn.afcollege.edu.au/login</a></li><li>Meet Australian student visa subclass 500 requirements; and</li><li>Have an IELTS* score of 6 (test results must be no more than 2 years old). English language competence can also be demonstrated through documented evidence of any of the following:<ul><li>Educated for at least 5 years in an English-speaking country where the medium of instructions was in English; or</li><li>Completed at least a Certificate IV level course in an Australian RTO within the last 2 years;</li></ul></li></ul><p><em>*Note that other English language tests such as PTE and TOEFL can be accepted. Students are required to provide their results so that Australian Federation College can confirm they are equivalent to IELTS 6. Refer to ECT for further guidance.</em></p></div>',
    apply_form = 'https://afcollege.edu.au/rii60520-advanced-diploma-of-civil-construction-design/',
    updated_at = NOW()
WHERE cricos_course_code = '114858B';
UPDATE courses SET
    course_description = '<div> <div> <p>The General English course is designed to prepare students for conversation, everyday situations and daily interactions that take place when travelling or living in an English-speaking country. Students learn and practice the four macro-skills of listening, reading, writing and speaking in an interactive environment. Levels of difficulty increase over the duration of the course to assist students to develop their skills and to be more confident and fluent in English.<br/>The course is structured into 6 levels (Starter, Elementary, Pre-intermediate, Intermediate, Upper Intermediate and Advanced). Each of the levels has a duration of 10 weeks (the study period) and the course in total is 70 weeks (including holidays). The specific outcomes for each level are detailed in the section of this curriculum document on course outcomes.</p> </div> </div>',
    total_course_duration = '10-70 weeks',
    offshore_tuition_fee = NULL,
    onshore_tuition_fee = NULL,
    enrolment_fee = NULL,
    materials_fee = NULL,
    entry_requirements = '<h4>Entry Requirements</h4><div><p>Australian Federation College has the following entry requirements:</p><ul><li>Be at least 18 years of age at course commencement;</li><li>For students studying this course alone, there is no IELTS requirement.</li><li>Students will be assessed by Australian Federation College during the enrolment process using the Oxford Placement Test and an interview. They will then be placed in the appropriate class level which is best suited to their needs.</li></ul></div>',
    apply_form = 'https://afcollege.edu.au/general-english-elicos/',
    updated_at = NOW()
WHERE cricos_course_code = '116758A';
